SELECT id, session_id, event_time, DENSE_RANK() OVER (PARTITION BY DATE_TRUNC('week', event_time), session_id ORDER BY duration_sec) AS duration_sec_dense_rank, FIRST_VALUE(page, TRUE) OVER (PARTITION BY MONTH(event_time), event_type ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_page, LEAD(duration_sec, 1) OVER (PARTITION BY event_type ORDER BY duration_sec, id) AS next_duration_sec, ROW_NUMBER() OVER (PARTITION BY TO_DATE(event_time), event_type ORDER BY event_time DESC, id) AS seq_no, LEAD(duration_sec, 1) OVER (ORDER BY duration_sec, id) AS next_duration_sec_2 FROM web_events;
